DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog"
        WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc' AND NOT is_active
          AND tool_specific_limits->>'runtime_commit' = '27e118a') <> 11 THEN
        RAISE EXCEPTION 'Expected eleven inactive market-ai-orc rows at runtime_commit 27e118a';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog"
        WHERE tool_name IN ('request_data', 'run_python_analysis', 'get_analysis_result') AND version = 'v1'
          AND tool_specific_limits->>'superseded_by' = 'v2'
          AND tool_specific_limits->>'runtime_commit' = '81475ae') <> 3 THEN
        RAISE EXCEPTION 'Expected the three superseded v1 rows to keep runtime_commit 81475ae';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog"
               WHERE is_active AND tool_specific_limits->>'runtime_service' = 'market-ai-orc') THEN
        RAISE EXCEPTION 'market-ai-orc rows must stay inactive';
    END IF;
END
$verify$;

COMMIT;
